(() => {
  const containers = [...document.querySelectorAll('[data-basketball-schedule]')];
  if (!containers.length) return;
  const fixtures = [...window.KAHSI_BASKETBALL_SCHEDULE].sort((a,b) => a.date.localeCompare(b.date));
  const escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const formatDay = (date, options) => new Date(`${date}T12:00:00-05:00`).toLocaleDateString('en-US', {timeZone:'America/New_York',...options});
  const timeText = game => game.startTime ? new Date(game.startTime).toLocaleTimeString('en-US', {hour:'numeric',minute:'2-digit',timeZone:'America/New_York'}) + ' ET' : 'Time TBA';
  function easternDay(now) {
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(now)).map(p=>[p.type,p.value]));
    return `${parts.year}-${parts.month}-${parts.day}`;
  }
  const isUpcoming = (game,now) => game.startTime ? Date.parse(game.startTime)>now : game.date>=easternDay(now);
  const dialog = document.createElement('dialog');
  dialog.className='highlights-dialog schedule-dialog';
  dialog.setAttribute('aria-labelledby','schedule-dialog-title');
  document.body.append(dialog);
  let activeGameId;
  let calendarURL;
  const confirmedTime = game => Boolean(game.startTime && Number.isFinite(Date.parse(game.startTime)));
  const eventAccent = game => game.kind==='Exhibition' && /Canada/i.test(game.event) ? 'canada' : /Hope Gas/i.test(game.event) ? 'hope-gas' : /Battle for the Armory/i.test(game.event) ? 'armory' : 'royal';
  const opponentName = game => game.opponent==='To Be Determined' ? 'Opponent TBA' : game.opponent;
  const separator = game => game.kind==='Away' ? 'AT' : 'VS';
  function calendarFile(game) {
    if (!confirmedTime(game)) return null;
    const local = Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(game.startTime)).map(p=>[p.type,p.value]));
    const stamp = new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
    const escapeICS = value => String(value).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
    const lines = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//KahsiMorgan.com//Basketball Schedule//EN','CALSCALE:GREGORIAN',
      'BEGIN:VTIMEZONE','TZID:America/New_York','X-LIC-LOCATION:America/New_York',
      'BEGIN:DAYLIGHT','TZOFFSETFROM:-0500','TZOFFSETTO:-0400','TZNAME:EDT','DTSTART:19700308T020000','RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=2SU','END:DAYLIGHT',
      'BEGIN:STANDARD','TZOFFSETFROM:-0400','TZOFFSETTO:-0500','TZNAME:EST','DTSTART:19701101T020000','RRULE:FREQ=YEARLY;BYMONTH=11;BYDAY=1SU','END:STANDARD','END:VTIMEZONE',
      'BEGIN:VEVENT',`UID:${game.id}@kahsimorgan.com`,`DTSTAMP:${stamp}`,
      `DTSTART;TZID=America/New_York:${local.year}${local.month}${local.day}T${local.hour}${local.minute}${local.second}`,
      `SUMMARY:${escapeICS(game.kind==='Exhibition'?game.title:'Capital '+game.title)}`,
      `LOCATION:${escapeICS([game.venue,game.address].filter(Boolean).join(', '))}`,
      `DESCRIPTION:${escapeICS([game.kind,game.event,game.note,'Kahsi Morgan - Capital High School basketball'].filter(Boolean).join(' · '))}`,
      'URL:https://kahsimorgan.com/basketball-schedule','END:VEVENT','END:VCALENDAR'];
    // Fold by UTF-8 octets, as required by iCalendar; no unconfirmed end time is invented.
    return lines.map(line=>{
      const chunks=[]; let chunk='', bytes=0;
      for (const char of line) {
        const size=new TextEncoder().encode(char).length;
        if (bytes+size>75) { chunks.push(chunk); chunk=' '; bytes=1; }
        chunk+=char; bytes+=size;
      }
      chunks.push(chunk); return chunks.join('\r\n');
    }).join('\r\n')+'\r\n';
  }
  function showGame(game) {
    activeGameId=game.id;
    if (calendarURL) { URL.revokeObjectURL(calendarURL); calendarURL=null; }
    dialog.dataset.eventAccent=eventAccent(game);
    dialog.dataset.gameKind=game.kind.toLowerCase();
    const hasTime=confirmedTime(game);
    const destination=game.address?encodeURIComponent(`${game.venue}, ${game.address}`):null;
    const maps=game.address?[
      ['Google Maps','google-maps',`https://www.google.com/maps/dir/?api=1&destination=${destination}&travelmode=driving`],
      ['Apple Maps','apple',`https://maps.apple.com/?daddr=${destination}&dirflg=d`],
      ['Waze','waze',`https://www.waze.com/ul?q=${encodeURIComponent(game.address)}&navigate=yes`]
    ]:[];
    const matchup=game.kind==='Exhibition'
      ? `<p class="game-capital-label">Capital High School</p><h2 id="schedule-dialog-title" class="game-special-title">${escapeHTML(game.title)}</h2>`
      : `<h2 id="schedule-dialog-title" class="game-matchup" aria-label="Capital High School ${separator(game).toLowerCase()} ${escapeHTML(opponentName(game))}"><span class="game-team"><span class="game-team-name">Capital</span></span><span class="game-versus">${separator(game)}</span><span class="game-team"><span class="game-team-name">${escapeHTML(opponentName(game))}</span></span></h2>`;
    if (hasTime) calendarURL=URL.createObjectURL(new Blob([calendarFile(game)],{type:'text/calendar;charset=utf-8'}));
    dialog.innerHTML=`
      <div class="game-modal-topbar"><span class="game-season-label">2026–27 Basketball</span><span class="game-location-badge">${escapeHTML(game.kind)}</span><button type="button" class="schedule-close" aria-label="Close game details">×</button></div>
      <header class="game-card-header">${matchup}</header>
      <div class="game-card-body">
        <div class="game-date-panel"><p class="game-when"><time datetime="${escapeHTML(game.date)}">${escapeHTML(formatDay(game.date,{weekday:'short',month:'short',day:'numeric',year:'numeric'}))}</time><span class="game-tipoff">${hasTime?escapeHTML(timeText(game)):'Tip-off TBA'}</span></p>
        ${!hasTime?'<p class="game-time-note">Game time will be added once confirmed.</p>':''}</div>
        ${game.event && game.kind!=='Exhibition' || game.note?`<div class="game-event-tags" data-event-accent="${eventAccent(game)}">${game.event && game.kind!=='Exhibition'?`<span>${escapeHTML(game.event)}</span>`:''}${game.note?`<span>${escapeHTML(game.note)}</span>`:''}</div>`:''}
        ${game.venue?`<div class="game-venue"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg><div><strong>${escapeHTML(game.venue)}</strong><address>${escapeHTML(game.address)}</address></div></div>`:'<p class="game-no-venue">No address or directions are listed for this exhibition.</p>'}
        <div class="game-controls">
          ${hasTime?`<a class="game-calendar" href="${calendarURL}" download="capital-${escapeHTML(game.id)}.ics">Add to Calendar <span aria-hidden="true">＋</span></a>`:''}
          ${maps.length?`<p class="game-directions-label" id="game-directions-label">Open directions in:</p><div id="game-map-options" class="schedule-map-links" role="group" aria-labelledby="game-directions-label">${maps.map(([name,icon,url])=>`<a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer" aria-label="Get directions with ${name} (opens in a new tab)"><img src="assets/maps/${icon}.svg" alt="" width="24" height="28"><span>${name}</span></a>`).join('')}</div>`:''}
        </div>
        <p class="game-timezone">All times Eastern</p>
      </div>`;
    dialog.querySelector('.schedule-close').addEventListener('click',()=>dialog.close());
    dialog.showModal();
    document.body.classList.add('schedule-dialog-open');
    dialog.querySelector('.schedule-close').focus();
  }
  function render() {
    // Keep the dialog and its originating keyboard focus stable during minute updates.
    if (dialog.open) return;
    const now=Date.now();
    containers.forEach(container=>{
      const upcoming=container.dataset.basketballSchedule==='upcoming';
      const games=upcoming?fixtures.filter(game=>isUpcoming(game,now)).slice(0,5):fixtures;
      let month='';
      container.innerHTML=games.length?games.map(game=>{
        const group=game.date.slice(0,7);
        const heading=!upcoming && month!==group?`<h3 class="schedule-month">${escapeHTML(formatDay(game.date,{month:'long',year:'numeric'}))}</h3>`:'';
        month=group;
        return `${heading}<button type="button" class="event-card schedule-game upcoming-game" data-event-accent="${eventAccent(game)}" data-game-kind="${game.kind.toLowerCase()}" data-game-id="${escapeHTML(game.id)}" aria-haspopup="dialog" aria-label="${escapeHTML(formatDay(game.date,{month:'long',day:'numeric'})+', '+game.title+', '+timeText(game)+'. View game details and directions')}">
          <time class="upcoming-date" datetime="${escapeHTML(game.date)}"><span>${escapeHTML(formatDay(game.date,{month:'short'}))}</span><b>${escapeHTML(formatDay(game.date,{day:'numeric'}))}</b><span>${escapeHTML(formatDay(game.date,{weekday:'short'}))}</span></time>
          <span class="upcoming-copy"><span class="upcoming-kicker">2026–27 Basketball <span class="upcoming-badge">${escapeHTML(game.kind)}</span></span>
          <strong>${game.kind==='Exhibition'?escapeHTML(game.title):`<em>${separator(game)}</em> ${escapeHTML(opponentName(game))}`}</strong>
          ${game.event && game.kind!=='Exhibition'?`<span class="upcoming-event">${escapeHTML(game.event)}</span>`:''}
          ${game.note?`<span class="upcoming-event">${escapeHTML(game.note)}</span>`:''}
          <span class="upcoming-footer"><span>${confirmedTime(game)?escapeHTML(timeText(game)):'Tip-off TBA'}</span><span>Game details <span aria-hidden="true">↗</span></span></span></span>
        </button>`;
      }).join(''):'<div class="schedule-empty"><h3>No upcoming games scheduled.</h3><p>Check back for new games.</p></div>';
    });
  }
  containers.forEach(container=>container.addEventListener('click',event=>{
    const button=event.target.closest('[data-game-id]');
    if (!button) return;
    const game=fixtures.find(game=>game.id===button.dataset.gameId);
    if (game) showGame(game);
  }));
  dialog.addEventListener('click',event=>{
    if (event.target!==dialog) return;
    const r=dialog.getBoundingClientRect();
    if (event.clientX<r.left || event.clientX>r.right || event.clientY<r.top || event.clientY>r.bottom) dialog.close();
  });
  // Native modal inertness plus an explicit Tab wrap keeps keyboard focus in the card.
  dialog.addEventListener('keydown',event=>{
    if (event.key!=='Tab') return;
    const controls=[...dialog.querySelectorAll('button:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length && !el.closest('[hidden]'));
    const first=controls[0],last=controls[controls.length-1];
    if (event.shiftKey && document.activeElement===first) { event.preventDefault(); last?.focus(); }
    else if (!event.shiftKey && document.activeElement===last) { event.preventDefault(); first?.focus(); }
  });
  dialog.addEventListener('close',()=>{
    if (calendarURL) { URL.revokeObjectURL(calendarURL); calendarURL=null; }
    document.body.classList.remove('schedule-dialog-open');
    render();
    (document.querySelector(`[data-game-id="${activeGameId}"]`) || containers[0].querySelector('.schedule-game'))?.focus({preventScroll:true});
  });
  render();
  window.setInterval(render,60000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});
})();
